WITH combined_sales AS ( SELECT ss.ss_item_sk AS item_sk, ss.ss_ext_discount_amt AS discount_amt, ss.ss_ext_sales_price AS sales_price, 'store' AS channel, NULL AS web_site_name FROM store_sales ss UNION ALL SELECT ws.ws_item_sk AS item_sk, ws.ws_ext_discount_amt AS discount_amt, ws.ws_ext_sales_price AS sales_price, 'web' AS channel, w.web_name AS web_site_name FROM web_sales ws JOIN web_site w ON ws.ws_web_site_sk = w.web_site_sk ) SELECT i.i_category, AVG(CASE WHEN cs.sales_price > 0 THEN cs.discount_amt / cs.sales_price ELSE 0 END) AS avg_discount_ratio, CASE WHEN AVG(CASE WHEN cs.sales_price > 0 THEN cs.discount_amt / cs.sales_price ELSE 0 END) > 0.20 THEN 'High' WHEN AVG(CASE WHEN cs.sales_price > 0 THEN cs.discount_amt / cs.sales_price ELSE 0 END) BETWEEN 0.10 AND 0.20 THEN 'Medium' ELSE 'Low' END AS discount_category, RANK() OVER (ORDER BY AVG(CASE WHEN cs.sales_price > 0 THEN cs.discount_amt / cs.sales_price ELSE 0 END) DESC) AS discount_rank FROM combined_sales cs JOIN item i ON i.i_item_sk = cs.item_sk GROUP BY i.i_category ORDER BY discount_rank LIMIT 10
